    zones: [['basar', 'Der große Basar', 'Seide, Gewürze und Lampen', -6, -26, 14], ['haus', 'Aladdins Elternhaus', 'Das Haus des Schneiders Mustafa', -40, -18, 8], ['palast', 'Palast des Sultans', 'Vierundzwanzig Fenster aus Juwelen', 6, -96, 16], ['hoehle', 'Die Schatzhöhle', 'Gärten mit Früchten aus Edelsteinen', -64, -72, 14], ['oase', 'Die Oase', 'Wasser, Palmen und Schatten', 46, -24, 12], ['zelt', 'Lager des Zauberers', 'Hier rechnet er in den Sternen', 70, -76, 12], ['hamam', 'Das Badehaus', 'Wo die Prinzessin baden ging', -36, -50, 9], ['karawane', 'Karawanserei', 'Kamele, Kisten und Geschichten', 34, -58, 11]],
